        return Power.FromSI(sum);
    }

    public static Power Average(this IEnumerable<Power> values)
    {
        double sum = 0; long count = 0;
        foreach (var v in values) { sum += v.SI; count++; }
        return count == 0 ? throw new InvalidOperationException("Sequence contains no elements") : Power.FromSI(sum / count);
    }

    public static Power Min(this IEnumerable<Power> values) => Aggregate(values, Math.Min);
    public static Power Max(this IEnumerable<Power> values) => Aggregate(values, Math.Max);

    private static Power Aggregate(IEnumerable<Power> values, Func<double, double, double> pick)
    {
        using var e = values.GetEnumerator();
        if (!e.MoveNext()) throw new InvalidOperationException("Sequence contains no elements");
        var result = e.Current.SI;
        while (e.MoveNext()) result = pick(result, e.Current.SI);
        return Power.FromSI(result);
    }
}
